import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import okhttp3.OkHttpClient
import okhttp3.Request
import org.json.JSONObject

class WeatherClient(
    private val http: OkHttpClient,
    private val baseUrl: String = "https://api.open-meteo.com/",
) {
    suspend fun currentTemperature(lat: Double, lon: Double): Double = withContext(Dispatchers.IO) {
        val request = Request.Builder()
            .url("${baseUrl}v1/forecast?latitude=$lat&longitude=$lon&current=temperature_2m")
            .build()
        http.newCall(request).execute().use { response ->
            check(response.isSuccessful) { "weather request failed: ${response.code}" }
            JSONObject(response.body!!.string()).getJSONObject("current").getDouble("temperature_2m")
        }
    }
}

